}

@layer base {
  * {
    @apply border-border;
  }

  body {
    @apply font-sans antialiased text-foreground;
    position: relative;
    overflow-x: hidden;
  }
}

@layer utilities {
  /* Hide search cancel button */
  input[type="search"]::-webkit-search-cancel-button {
    @apply hidden;
  }

  /* Placeholder for contentEditable */
  [contenteditable][data-placeholder]:empty::before {
    content: attr(data-placeholder);
    color: hsl(var(--muted-foreground));
    pointer-events: none;
  }

  /* Premium Glassmorphism Utilities */
  .glass {
    background: var(--glass-bg) !important;
    backdrop-filter: blur(20px) !important;
    -webkit-backdrop-filter: blur(20px) !important;
    border: 1px solid var(--glass-border) !important;
  }

  .glass-card {
    background: var(--glass-bg) !important;
    backdrop-filter: blur(24px) !important;
    -webkit-backdrop-filter: blur(24px) !important;
    border: 1.5px solid var(--glass-border) !important;
    box-shadow: var(--shadow-depth-2) !important;
    transition: all 0.4s var(--ease-smooth);
  }

  .glass-card:hover {
    box-shadow: var(--shadow-depth-3), var(--shadow-glow-sm) !important;
    background: var(--glass-hover) !important;
  }

  /* Gradient Text */
  .gradient-text {
    background: linear-gradient(135deg, hsl(var(--gradient-from)) 0%, hsl(var(--gradient-to)) 100%);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
  }

  /* Gradient Borders */
  .gradient-border {
    position: relative;
    background: var(--glass-bg) !important;
    backdrop-filter: blur(20px) !important;
    -webkit-backdrop-filter: blur(20px) !important;
    box-shadow: var(--shadow-depth-2) !important;
  }

  .gradient-border::before {
    content: "";
    position: absolute;
    inset: 0;
    border-radius: inherit;
    padding: 1.5px;
    background: linear-gradient(135deg, hsl(var(--gradient-from)), hsl(var(--gradient-to)));
    -webkit-mask: linear-gradient(#fff 0 0) content-box, linear-gradient(#fff 0 0);
    -webkit-mask-composite: xor;
    mask-composite: exclude;
    pointer-events: none;
  }

  /* Premium Shimmer Effect */
  .shimmer {
    position: relative;
    overflow: hidden;
  }

  .shimmer::after {
    content: "";
    position: absolute;
    top: 0;
    right: 0;
    bottom: 0;
    left: 0;
    background: linear-gradient(90deg, transparent, rgba(255, 255, 255, 0.2), transparent);
    transform: translateX(-100%);
    animation: shimmer 2s infinite;
  }

  @keyframes shimmer {
    100% {
      transform: translateX(100%);
    }
  }

  /* Glow Effect */
  .glow {
    box-shadow: var(--shadow-glow-md);
    transition: box-shadow 0.3s var(--ease-smooth);
  }

  .glow:hover {
    box-shadow: var(--shadow-glow-lg);
  }

  /* Escape hatch utilities */
  .no-default-hover-elevate {}
  .no-default-active-elevate {}

  /* Toggle Elevation System */
  .toggle-elevate::before,
  .toggle-elevate-2::before {
    content: "";
    pointer-events: none;
    position: absolute;
    inset: 0px;
    border-radius: inherit;
    z-index: -1;
  }

  .toggle-elevate.toggle-elevated::before {
    background-color: var(--elevate-2);
  }

  .border.toggle-elevate::before {
    inset: -1px;
  }

  /* Hover & Active Elevation */
  .hover-elevate:not(.no-default-hover-elevate),
  .active-elevate:not(.no-default-active-elevate),
  .hover-elevate-2:not(.no-default-hover-elevate),
  .active-elevate-2:not(.no-default-active-elevate) {
    position: relative;
    z-index: 0;
    transition: all 0.25s var(--ease-smooth);
  }

  .hover-elevate:not(.no-default-hover-elevate)::after,
  .active-elevate:not(.no-default-active-elevate)::after,
  .hover-elevate-2:not(.no-default-hover-elevate)::after,
  .active-elevate-2:not(.no-default-active-elevate)::after {
    content: "";
    pointer-events: none;
    position: absolute;
    inset: 0px;
    border-radius: inherit;
    z-index: 999;
    transition: background-color 0.25s var(--ease-smooth);
  }

  .hover-elevate:hover:not(.no-default-hover-elevate)::after,
  .active-elevate:active:not(.no-default-active-elevate)::after {
    background-color: var(--elevate-1);
  }

  .hover-elevate-2:hover:not(.no-default-hover-elevate)::after,
  .active-elevate-2:active:not(.no-default-active-elevate)::after {
    background-color: var(--elevate-2);
  }

  .border.hover-elevate:not(.no-hover-interaction-elevate)::after,
  .border.active-elevate:not(.no-active-interaction-elevate)::after,
  .border.hover-elevate-2:not(.no-hover-interaction-elevate)::after,
  .border.active-elevate-2:not(.no-active-interaction-elevate)::after {
    inset: -1px;
  }

  /* Premium Pulse Animation */
  .pulse-glow {
    animation: pulse-glow 2s ease-in-out infinite;
  }

  @keyframes pulse-glow {
    0%, 100% {
      box-shadow: var(--shadow-glow-sm);
    }
    50% {
      box-shadow: var(--shadow-glow-md);
    }
  }

  /* Icon Hover Animations - Premium micro-interactions */
  .icon-hover {
    transition: all 0.25s var(--ease-smooth);
  }

  .icon-hover:hover {
    transform: rotate(5deg) scale(1.1);
  }

  /* Parallax Effect - Subtle depth on scroll/hover */
  .parallax-sm {
    transition: transform 0.3s var(--ease-smooth);
  }

  .parallax-sm:hover {
    transform: translateZ(0) translateY(-2px);
  }

  .parallax-md {
    transition: transform 0.4s var(--ease-smooth);
  }

  .parallax-md:hover {
    transform: translateZ(0) translateY(-4px);
  }

  /* Glow Effect Utilities */
  .glow-on-hover {
    transition: box-shadow 0.4s var(--ease-smooth);
  }

  .glow-on-hover:hover {
    box-shadow: var(--shadow-depth-2), var(--shadow-glow-md) !important;
  }

  .glow-primary {
    box-shadow: 0 0 20px rgba(102, 126, 234, 0.3);
  }

  .glow-accent {
    box-shadow: 0 0 20px rgba(139, 92, 246, 0.3);
  }

  /* Smooth Scale on Hover - Premium buttons */
  .scale-hover {
    transition: transform 0.25s var(--ease-smooth);
  }

  .scale-hover:hover {
    transform: scale(1.02);
  }

  /* Depth Layering */
  .depth-1 {
    box-shadow: var(--shadow-depth-1) !important;
  }

  .depth-2 {
    box-shadow: var(--shadow-depth-2) !important;
  }

  .depth-3 {
    box-shadow: var(--shadow-depth-3) !important;
  }
}

