        description: objective.description || "",
        orderIndex: objective.orderIndex.toString(),
      });
    } else {
      setFormData({
        type: "CONCEPT",
        title: "",
        description: "",
        orderIndex: "0",
      });
    }
  }, [objective, isOpen]);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    onSubmit({
      ...formData,
      weekId,
      orderIndex: parseInt(formData.orderIndex),
    });
  };

  return (
    <Dialog open={isOpen} onOpenChange={onClose}>
