import { Card } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { BookOpen, Video, GraduationCap, FileText, ExternalLink, Pencil, Trash2 } from "lucide-react";
import type { Resource } from "@shared/schema";
import { isMentor } from "@/lib/auth";

interface ResourcesListProps {
  resources: Resource[];
  onEdit?: (resource: Resource) => void;
  onDelete?: (resourceId: number) => void;
}

const resourceIcons = {
  DOC: FileText,
  VIDEO: Video,
  COURSE: GraduationCap,
  ARTICLE: BookOpen,
  OTHER: FileText,
};

const resourceColorClasses = {
  DOC: "bg-warning",
  VIDEO: "bg-destructive",
  COURSE: "bg-accent",
  ARTICLE: "bg-primary",
  OTHER: "bg-muted",
};

const resourceTypeLabels = {
  DOC: "Documentation",
  VIDEO: "Vidéo",
  COURSE: "Cours",
  ARTICLE: "Article",
  OTHER: "Autre",
};

export function ResourcesList({ resources, onEdit, onDelete }: ResourcesListProps) {
  if (resources.length === 0) {
    return (
      <Card className="bg-card rounded-xl p-6 shadow-sm text-center">
        <BookOpen className="w-12 h-12 text-muted-foreground mx-auto mb-2" />
        <p className="text-muted-foreground text-sm">Aucune ressource disponible</p>
      </Card>
    );
  }

  return (
    <div className="space-y-3">
      {resources.map((resource) => {
        const Icon = resourceIcons[resource.resourceType as keyof typeof resourceIcons] || FileText;
        const colorClass = resourceColorClasses[resource.resourceType as keyof typeof resourceColorClasses];
        const typeLabel = resourceTypeLabels[resource.resourceType as keyof typeof resourceTypeLabels];

        return (
          <Card
            key={resource.id}
            className="bg-card rounded-xl p-4 shadow-md group hover:shadow-lg transition-shadow"
            data-testid={`card-resource-${resource.id}`}
          >
            <div className="flex items-center justify-between">
              <div className="flex items-center gap-3 flex-1">
                <div className={`w-10 h-10 rounded-lg flex items-center justify-center shadow-sm flex-shrink-0 ${colorClass}`}>
                  <Icon className="w-5 h-5 text-white" />
                </div>
                <div className="flex-1 min-w-0">
                  <div className="flex items-center gap-2 mb-1">
                    <Badge className="bg-muted text-foreground border-0 text-xs">
                      {typeLabel}
                    </Badge>
                  </div>
                  <h4 className="text-foreground font-medium text-sm truncate">
                    {resource.label}
                  </h4>
                </div>
              </div>

              <div className="flex items-center gap-1 ml-3">
                <Button
                  size="icon"
                  variant="ghost"
                  asChild
                  className="h-8 w-8"
                  data-testid={`button-open-resource-${resource.id}`}
                >
                  <a href={resource.url} target="_blank" rel="noopener noreferrer">
                    <ExternalLink className="w-4 h-4" />
                  </a>
                </Button>

                {isMentor() && (
                  <div className="flex gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                    <Button
                      size="icon"
                      variant="ghost"
                      onClick={() => onEdit?.(resource)}
                      className="h-8 w-8"
                      data-testid={`button-edit-resource-${resource.id}`}
                    >
                      <Pencil className="w-4 h-4" />
                    </Button>
                    <Button
                      size="icon"
                      variant="ghost"
                      onClick={() => onDelete?.(resource.id)}
                      className="bg-destructive/10 text-destructive h-8 w-8"
                      data-testid={`button-delete-resource-${resource.id}`}
                    >
                      <Trash2 className="w-4 h-4" />
                    </Button>
                  </div>
                )}
              </div>
            </div>
          </Card>
        );
      })}
    </div>
  );
}

client/src/components/progress-panel.tsx.content:
import { Card } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { TrendingUp, CheckCircle2, Circle, Target } from "lucide-react";

interface ProgressStats {
  globalPercentage: number;
  totalCompleted: number;
  totalTasks: number;
  weeklyProgress: {
    weekNumber: number;
    weekTitle: string;
    completed: number;
    total: number;
    percentage: number;
  }[];
}

interface ProgressPanelProps {
  stats: ProgressStats;
}

export function ProgressPanel({ stats }: ProgressPanelProps) {
  return (
    <div className="space-y-5">
      {/* Global Progress */}
      <Card className="glass-card rounded-2xl p-7 gradient-border">
        <div className="flex items-center gap-4 mb-5">
          <div className="w-14 h-14 rounded-2xl bg-gradient-to-br from-success to-cyan-500 flex items-center justify-center shadow-xl glow">
            <TrendingUp className="w-7 h-7 text-white" />
          </div>
          <div>
            <h3 className="text-foreground font-bold text-lg gradient-text">Progression Globale</h3>
            <p className="text-muted-foreground text-xs font-medium">Toutes semaines confondues</p>
          </div>
        </div>

        <div className="space-y-4">
          <div className="flex items-baseline justify-between">
            <span className="text-muted-foreground text-sm font-semibold">Tâches complétées</span>
            <span className="text-foreground font-bold text-3xl gradient-text" data-testid="text-global-percentage">
              {stats.globalPercentage}%
            </span>
          </div>

          <div className="h-4 glass rounded-full overflow-hidden">
            <div
              className="h-full bg-gradient-to-r from-success to-cyan-500 transition-all duration-700 rounded-full shadow-lg pulse-glow"
              style={{ width: `${stats.globalPercentage}%` }}
            />
          </div>

          <div className="flex items-center justify-between text-xs">
            <span className="text-muted-foreground font-semibold">
              {stats.totalCompleted} / {stats.totalTasks} tâches
            </span>
            <Badge className="glass border-success/30 text-success font-bold shadow-md">
              {stats.totalTasks - stats.totalCompleted} restantes
            </Badge>
          </div>
        </div>
      </Card>

      {/* Weekly Breakdown */}
      <Card className="glass-card rounded-2xl p-7">
        <div className="flex items-center gap-3 mb-5">
          <Target className="w-6 h-6 text-primary icon-hover" />
          <h3 className="text-foreground font-bold text-lg">Par Semaine</h3>
        </div>

        <div className="space-y-4">
          {stats.weeklyProgress.length === 0 ? (
            <p className="text-muted-foreground text-sm text-center py-6 font-medium">
              Aucune donnée de progression
            </p>
          ) : (
            stats.weeklyProgress.map((week) => (
              <div key={week.weekNumber} className="space-y-2 glass p-4 rounded-xl hover-elevate transition-all duration-300" data-testid={`progress-week-${week.weekNumber}`}>
                <div className="flex items-center justify-between">
                  <div className="flex items-center gap-3">
                    <div className="w-9 h-9 rounded-xl bg-gradient-to-br from-primary to-accent flex items-center justify-center text-white text-xs font-bold shadow-lg pulse-glow">
                      S{week.weekNumber}
                    </div>
                    <span className="text-foreground text-sm font-semibold truncate max-w-[140px]">
                      {week.weekTitle}
                    </span>
                  </div>
                  <span className="text-foreground font-bold text-sm gradient-text">
                    {week.percentage}%
                  </span>
                </div>

                <div className="h-2.5 glass rounded-full overflow-hidden">
                  <div
                    className="h-full bg-gradient-to-r from-primary to-accent transition-all duration-500 rounded-full shadow-md"
                    style={{ width: `${week.percentage}%` }}
                  />
                </div>

                <div className="flex items-center justify-between text-xs text-muted-foreground font-medium">
                  <span>{week.completed}/{week.total}</span>
                  {week.percentage === 100 && (
                    <CheckCircle2 className="w-5 h-5 text-success drop-shadow-lg icon-hover" />
                  )}
                </div>
              </div>
            ))
          )}
        </div>
      </Card>

      {/* Motivation Badge */}
      <Card className="glass-card rounded-2xl p-7 text-center gradient-border glow-on-hover">
        <div className="mb-3">
          {stats.globalPercentage === 100 ? (
            <CheckCircle2 className="w-12 h-12 text-success mx-auto icon-hover pulse-glow" />
          ) : stats.globalPercentage >= 75 ? (
            <TrendingUp className="w-12 h-12 text-primary mx-auto icon-hover pulse-glow" />
          ) : stats.globalPercentage >= 50 ? (
            <Target className="w-12 h-12 text-warning mx-auto icon-hover" />
          ) : stats.globalPercentage >= 25 ? (
            <Circle className="w-12 h-12 text-destructive mx-auto icon-hover" />
          ) : (
            <Circle className="w-12 h-12 text-muted-foreground mx-auto icon-hover" />
          )}
        </div>
        <p className="text-foreground font-semibold text-sm">
          {stats.globalPercentage === 100
            ? "Bravo ! Toutes les tâches sont complétées !"
            : stats.globalPercentage >= 75
            ? "Excellent travail ! Continue !"
            : stats.globalPercentage >= 50
            ? "À mi-chemin ! Tu assures !"
            : stats.globalPercentage >= 25
            ? "Bon départ ! Continue sur cette lancée !"
            : "C'est parti ! Chaque tâche compte !"}
        </p>
      </Card>
    </div>
  );
}

client/src/components/task-list.tsx.content:
import { useState } from "react";
import { Checkbox } from "@/components/ui/checkbox";
import { Button } from "@/components/ui/button";
import { Tooltip, TooltipContent, TooltipTrigger } from "@/components/ui/tooltip";
import { Badge } from "@/components/ui/badge";
import { Pencil, Trash2, Image as ImageIcon, Users } from "lucide-react";
import type { Task, TaskProgressWithLearner } from "@shared/schema";
import { isMentor, isLearner, getCurrentUser } from "@/lib/auth";
import { ScreenshotUploader } from "./ScreenshotUploader";

interface TaskWithProgress extends Task {
  progress?: TaskProgressWithLearner[];
}

interface TaskListProps {
  tasks: TaskWithProgress[];
  onToggleTask?: (taskId: number, screenshotUrl?: string) => void;
  onEditTask?: (taskId: number) => void;
  onDeleteTask?: (taskId: number) => void;
}

export function TaskList({ tasks, onToggleTask, onEditTask, onDeleteTask }: TaskListProps) {
  const currentUser = getCurrentUser();
  const [pendingScreenshots, setPendingScreenshots] = useState<Record<number, string>>({});

  const isTaskCompleted = (task: TaskWithProgress): boolean => {
    if (!task.progress || task.progress.length === 0) return false;

    if (isMentor()) {
      // For mentors, show as completed if ANY learner has completed it
      return task.progress.some(p => p.isDone);
    } else {
      // For learners, check their own progress
      const userProgress = task.progress.find(p => p.learnerId === currentUser?.id);
      return userProgress?.isDone || false;
    }
  };

  const getTaskProgress = (task: TaskWithProgress): TaskProgressWithLearner | undefined => {
    if (!task.progress || task.progress.length === 0) return undefined;
    return task.progress.find(p => p.learnerId === currentUser?.id);
  };

  const getCompletedLearners = (task: TaskWithProgress): TaskProgressWithLearner[] => {
    if (!task.progress) return [];
    return task.progress.filter(p => p.isDone);
  };

  const handleScreenshotUpload = (taskId: number, url: string) => {
    setPendingScreenshots(prev => ({ ...prev, [taskId]: url }));
    // Auto-complete the task after screenshot upload
    onToggleTask?.(taskId, url);
  };

  if (tasks.length === 0) {
    return (
      <div className="text-center py-6">
        <p className="text-muted-foreground text-sm font-medium">Aucune tâche pour le moment</p>
      </div>
    );
  }

  return (
    <ul className="space-y-0">
      {tasks.map((task, index) => {
        const isCompleted = isTaskCompleted(task);

        return (
          <li
            key={task.id}
            className={`
              flex items-start gap-4 py-4 group glass rounded-xl px-3 my-2
              hover:shadow-md transition-all duration-300
            `}
            data-testid={`task-item-${task.id}`}
          >
            {isLearner() ? (
              <Tooltip>
                <TooltipTrigger asChild>
                  <div>
                    <Checkbox
                      checked={isCompleted}
                      disabled={!isCompleted}
                      onCheckedChange={() => {
                        if (isCompleted) {
                          // Allow unchecking a completed task
                          onToggleTask?.(task.id);
                        }
                      }}
                      className="mt-0.5 data-[state=checked]:bg-gradient-to-br data-[state=checked]:from-success data-[state=checked]:to-cyan-500 data-[state=checked]:border-success shadow-md disabled:opacity-50 disabled:cursor-not-allowed"
                      data-testid={`checkbox-task-${task.id}`}
                    />
                  </div>
                </TooltipTrigger>
                {!isCompleted && (
                  <TooltipContent>
                    <p>Joignez la capture d'écran de réussite de l'exercice</p>
                  </TooltipContent>
                )}
              </Tooltip>
            ) : (
              <div className={`w-5 h-5 rounded-lg border-2 mt-0.5 flex-shrink-0 shadow-md ${
                isCompleted 
                  ? "bg-gradient-to-br from-success to-cyan-500 border-success" 
                  : "border-white/20 glass"
              }`} />
            )}

            <div className="flex-1 flex flex-col gap-2">
              <span
                className={`
                  text-sm leading-relaxed transition-all font-medium
                  ${isCompleted 
                    ? "text-muted-foreground line-through opacity-60" 
                    : "text-foreground"
                  }
                `}
              >
                {task.label}
                {task.isOptional && (
                  <span className="ml-2 text-xs text-muted-foreground italic font-semibold">(optionnel)</span>
                )}
              </span>

              {isLearner() && (
                <div className="flex items-center gap-2 flex-wrap">
                  {isCompleted && getTaskProgress(task)?.screenshotUrl && (
                    <a 
                      href={getTaskProgress(task)!.screenshotUrl!} 
                      target="_blank" 
                      rel="noopener noreferrer"
                      className="flex items-center gap-1 text-xs text-primary hover:underline"
                      data-testid={`link-screenshot-${task.id}`}
                    >
                      <ImageIcon className="w-3 h-3" />
                      Voir la capture
                    </a>
                  )}
                  {!isCompleted && (
                    <ScreenshotUploader
                      onUploadComplete={(url) => handleScreenshotUpload(task.id, url)}
                      currentUrl={pendingScreenshots[task.id] || getTaskProgress(task)?.screenshotUrl}
                    />
                  )}
                </div>
              )}

              {isMentor() && (
                <div className="flex flex-col gap-2">
                  {getCompletedLearners(task).length > 0 && (
                    <div className="flex items-center gap-2">
                      <Badge variant="secondary" className="text-xs">
                        <Users className="w-3 h-3 mr-1" />
                        {getCompletedLearners(task).length} complété{getCompletedLearners(task).length > 1 ? 's' : ''}
                      </Badge>
                    </div>
                  )}
                  {getCompletedLearners(task).map((progress) => (
                    <div key={progress.id} className="flex items-center gap-2 text-xs">
                      <span className="text-muted-foreground font-medium">
                        {progress.learner?.fullName || `Apprenant #${progress.learnerId}`}:
                      </span>
                      {progress.screenshotUrl && (
                        <a 
                          href={progress.screenshotUrl} 
                          target="_blank" 
                          rel="noopener noreferrer"
                          className="flex items-center gap-1 text-primary hover:underline"
                          data-testid={`link-screenshot-${task.id}-${progress.learnerId}`}
                        >
                          <ImageIcon className="w-3 h-3" />
                          Voir la capture
                        </a>
                      )}
                    </div>
                  ))}
                </div>
              )}
            </div>

            {isMentor() && (
              <div className="flex gap-2 opacity-0 group-hover:opacity-100 transition-all duration-300">
                <Button
                  size="icon"
                  variant="ghost"
                  onClick={() => onEditTask?.(task.id)}
                  className="glass border-white/20 hover:border-white/30 shadow-lg"
                  data-testid={`button-edit-task-${task.id}`}
                >
                  <Pencil className="w-3.5 h-3.5" />
                </Button>
                <Button
                  size="icon"
                  variant="ghost"
                  onClick={() => onDeleteTask?.(task.id)}
                  className="glass border-destructive/30 text-destructive hover:border-destructive/50 shadow-lg"
                  data-testid={`button-delete-task-${task.id}`}
                >
                  <Trash2 className="w-3.5 h-3.5" />
                </Button>
              </div>
            )}
          </li>
        );
      })}
    </ul>
  );
}

