client/src/components/week-detail.tsx.content:
import { Card } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Calendar, CheckCircle2, Plus, Pencil, Trash2 } from "lucide-react";
import { ObjectiveCard } from "./objective-card";
import { DeliverablesList } from "./deliverables-list";
import { ResourcesList } from "./resources-list";
import { WeekComments } from "./week-comments";
import type { WeekWithDetails, ObjectiveWithTasks, Deliverable, Resource } from "@shared/schema";
import { isMentor } from "@/lib/auth";

interface WeekDetailProps {
  week: WeekWithDetails | null;
  onToggleTask?: (taskId: number, screenshotUrl?: string) => void;
  onAddComment?: (content: string) => void;
  onEditWeek?: () => void;
  onDeleteWeek?: () => void;
  onCloneWeek?: () => void;
  onValidateWeek?: () => void;
  onAddObjective?: () => void;
  onEditObjective?: (objective: ObjectiveWithTasks) => void;
  onDeleteObjective?: (objectiveId: number) => void;
  onCloneObjective?: (objectiveId: number) => void;
  onAddTask?: (objectiveId: number) => void;
  onEditTask?: (taskId: number) => void;
  onDeleteTask?: (taskId: number) => void;
  onAddDeliverable?: () => void;
  onEditDeliverable?: (deliverable: Deliverable) => void;
  onDeleteDeliverable?: (deliverableId: number) => void;
  onAddResource?: () => void;
  onEditResource?: (resource: Resource) => void;
  onDeleteResource?: (resourceId: number) => void;
  isLoadingComment?: boolean;
}

export function WeekDetail({
  week,
  onToggleTask,
  onAddComment,
  onEditWeek,
  onDeleteWeek,
  onCloneWeek,
  onValidateWeek,
  onAddObjective,
  onEditObjective,
  onDeleteObjective,
  onCloneObjective,
  onAddTask,
  onEditTask,
  onDeleteTask,
  onAddDeliverable,
  onEditDeliverable,
  onDeleteDeliverable,
  onAddResource,
  onEditResource,
  onDeleteResource,
  isLoadingComment,
}: WeekDetailProps) {
  if (!week) {
    return (
      <Card className="bg-card rounded-xl p-12 shadow-md text-center">
        <Calendar className="w-16 h-16 text-muted-foreground mx-auto mb-4" />
        <h3 className="text-foreground text-xl font-bold mb-2">Sélectionnez une semaine</h3>
        <p className="text-muted-foreground">
          Choisissez une semaine dans la liste de gauche pour voir les détails
        </p>
      </Card>
    );
  }

  const objectivesByType = {
    CONCEPT: week.objectives.filter(obj => obj.type === "CONCEPT"),
    ALGO: week.objectives.filter(obj => obj.type === "ALGO"),
    PROJECT: week.objectives.filter(obj => obj.type === "PROJECT"),
    OTHER: week.objectives.filter(obj => obj.type === "OTHER"),
  };

  return (
    <div className="space-y-4">
      {/* Week Header */}
      <Card className="bg-card rounded-xl p-6 shadow-md">
        <div className="flex items-start justify-between mb-4">
          <div className="flex-1">
            <div className="flex items-center gap-3 mb-2">
              <Badge className="bg-primary text-white border-0">
                Semaine {week.number}
              </Badge>
              {week.isValidatedByMentor && (
                <Badge className="bg-success/10 text-success border-0">
                  <CheckCircle2 className="w-3 h-3 mr-1" />
                  Validée
                </Badge>
              )}
            </div>
            <h2 className="text-2xl font-bold text-foreground mb-2">{week.title}</h2>
            <div className="flex items-center gap-2 text-muted-foreground text-sm">
              <Calendar className="w-4 h-4" />
              <span>{week.startDate} - {week.endDate}</span>
            </div>
            {week.description && (
              <p className="mt-3 text-foreground text-sm leading-relaxed">{week.description}</p>
            )}
          </div>

          {isMentor() && (
            <div className="flex gap-2 ml-4">
              <Button
                onClick={onCloneWeek}
                size="sm"
                variant="outline"
                data-testid="button-clone-week"
              >
                <Plus className="w-4 h-4 mr-1" />
                Dupliquer
              </Button>
              {!week.isValidatedByMentor && (
                <Button
                  onClick={onValidateWeek}
                  className="bg-success text-success-foreground"
                  data-testid="button-validate-week"
                >
                  <CheckCircle2 className="w-4 h-4 mr-2" />
                  Valider
                </Button>
              )}
              <Button
                size="icon"
                variant="outline"
                onClick={onEditWeek}
                data-testid="button-edit-week"
              >
                <Pencil className="w-4 h-4" />
              </Button>
              <Button
                size="icon"
                variant="outline"
                onClick={onDeleteWeek}
                className="bg-destructive/10 border-destructive/30 text-destructive"
                data-testid="button-delete-week"
              >
                <Trash2 className="w-4 h-4" />
              </Button>
            </div>
          )}
        </div>
      </Card>

      {/* Objectives */}
      <div className="space-y-3">
        <div className="flex items-center justify-between">
          <h3 className="text-xl font-bold text-foreground">Objectifs</h3>
          {isMentor() && (
            <Button
              onClick={onAddObjective}
              className="bg-primary text-white"
              data-testid="button-add-objective"
            >
              <Plus className="w-4 h-4 mr-2" />
              Ajouter un objectif
            </Button>
          )}
        </div>

        {week.objectives.length === 0 ? (
          <Card className="bg-card rounded-xl p-8 shadow-sm text-center">
            <p className="text-muted-foreground">Aucun objectif défini pour cette semaine</p>
          </Card>
        ) : (
          <div className="grid grid-cols-1 md:grid-cols-[repeat(auto-fit,minmax(22rem,1fr))] gap-6">
            {week.objectives.map((objective) => (
              <ObjectiveCard
                key={objective.id}
                objective={objective}
                onToggleTask={onToggleTask}
                onEditObjective={onEditObjective}
                onDeleteObjective={onDeleteObjective}
                onCloneObjective={onCloneObjective}
                onAddTask={onAddTask}
                onEditTask={onEditTask}
                onDeleteTask={onDeleteTask}
              />
            ))}
          </div>
        )}
      </div>

      {/* Deliverables */}
      <div className="space-y-3">
        <div className="flex items-center justify-between">
          <h3 className="text-xl font-bold text-foreground">Livrables Attendus</h3>
          {isMentor() && (
            <Button
              onClick={onAddDeliverable}
              className="bg-success text-success-foreground"
              data-testid="button-add-deliverable"
            >
              <Plus className="w-4 h-4 mr-2" />
              Ajouter un livrable
            </Button>
          )}
        </div>
        <DeliverablesList
          deliverables={week.deliverables}
          onEdit={onEditDeliverable}
          onDelete={onDeleteDeliverable}
        />
      </div>

      {/* Resources */}
      <div className="space-y-3">
        <div className="flex items-center justify-between">
          <h3 className="text-xl font-bold text-foreground">Ressources Recommandées</h3>
          {isMentor() && (
            <Button
              onClick={onAddResource}
              className="bg-warning text-warning-foreground"
              data-testid="button-add-resource"
            >
              <Plus className="w-4 h-4 mr-2" />
              Ajouter une ressource
            </Button>
          )}
        </div>
        <ResourcesList
          resources={week.resources}
          onEdit={onEditResource}
          onDelete={onDeleteResource}
        />
      </div>

      {/* Comments */}
      <WeekComments
        comments={week.comments}
        onAddComment={onAddComment}
        isLoading={isLoadingComment}
      />
    </div>
  );
}

client/src/components/ui/chart.tsx.content:
"use client"

import * as React from "react"
import * as RechartsPrimitive from "recharts"

import { cn } from "@/lib/utils"

// Format: { THEME_NAME: CSS_SELECTOR }
const THEMES = { light: "", dark: ".dark" } as const

export type ChartConfig = {
  [k in string]: {
    label?: React.ReactNode
    icon?: React.ComponentType
  } & (
    | { color?: string; theme?: never }
    | { color?: never; theme: Record<keyof typeof THEMES, string> }
  )
}

type ChartContextProps = {
  config: ChartConfig
}

const ChartContext = React.createContext<ChartContextProps | null>(null)

function useChart() {
  const context = React.useContext(ChartContext)

  if (!context) {
    throw new Error("useChart must be used within a <ChartContainer />")
  }

  return context
}

const ChartContainer = React.forwardRef<
  HTMLDivElement,
  React.ComponentProps<"div"> & {
    config: ChartConfig
    children: React.ComponentProps<
      typeof RechartsPrimitive.ResponsiveContainer
    >["children"]
  }
>(({ id, className, children, config, ...props }, ref) => {
  const uniqueId = React.useId()
  const chartId = `chart-${id || uniqueId.replace(/:/g, "")}`

  return (
    <ChartContext.Provider value={{ config }}>
      <div
        data-chart={chartId}
        ref={ref}
        className={cn(
          "flex aspect-video justify-center text-xs [&_.recharts-cartesian-axis-tick_text]:fill-muted-foreground [&_.recharts-cartesian-grid_line[stroke='#ccc']]:stroke-border/50 [&_.recharts-curve.recharts-tooltip-cursor]:stroke-border [&_.recharts-dot[stroke='#fff']]:stroke-transparent [&_.recharts-layer]:outline-none [&_.recharts-polar-grid_[stroke='#ccc']]:stroke-border [&_.recharts-radial-bar-background-sector]:fill-muted [&_.recharts-rectangle.recharts-tooltip-cursor]:fill-muted [&_.recharts-reference-line_[stroke='#ccc']]:stroke-border [&_.recharts-sector[stroke='#fff']]:stroke-transparent [&_.recharts-sector]:outline-none [&_.recharts-surface]:outline-none",
          className
        )}
        {...props}
      >
        <ChartStyle id={chartId} config={config} />
        <RechartsPrimitive.ResponsiveContainer>
          {children}
        </RechartsPrimitive.ResponsiveContainer>
      </div>
    </ChartContext.Provider>
  )
})
ChartContainer.displayName = "Chart"

const ChartStyle = ({ id, config }: { id: string; config: ChartConfig }) => {
  const colorConfig = Object.entries(config).filter(
    ([, config]) => config.theme || config.color
  )

  if (!colorConfig.length) {
    return null
  }

  return (
    <style
      dangerouslySetInnerHTML={{
        __html: Object.entries(THEMES)
          .map(
            ([theme, prefix]) => `
${prefix} [data-chart=${id}] {
${colorConfig
  .map(([key, itemConfig]) => {
    const color =
      itemConfig.theme?.[theme as keyof typeof itemConfig.theme] ||
      itemConfig.color
    return color ? `  --color-${key}: ${color};` : null
  })
  .join("\n")}
}
`
          )
          .join("\n"),
      }}
    />
  )
}

const ChartTooltip = RechartsPrimitive.Tooltip

const ChartTooltipContent = React.forwardRef<
  HTMLDivElement,
  React.ComponentProps<typeof RechartsPrimitive.Tooltip> &
    React.ComponentProps<"div"> & {
      hideLabel?: boolean
      hideIndicator?: boolean
      indicator?: "line" | "dot" | "dashed"
      nameKey?: string
      labelKey?: string
    }
>(
  (
    {
      active,
      payload,
      className,
      indicator = "dot",
      hideLabel = false,
      hideIndicator = false,
      label,
      labelFormatter,
      labelClassName,
      formatter,
      color,
      nameKey,
      labelKey,
    },
    ref
  ) => {
    const { config } = useChart()

    const tooltipLabel = React.useMemo(() => {
      if (hideLabel || !payload?.length) {
        return null
      }

      const [item] = payload
      const key = `${labelKey || item?.dataKey || item?.name || "value"}`
      const itemConfig = getPayloadConfigFromPayload(config, item, key)
      const value =
        !labelKey && typeof label === "string"
          ? config[label as keyof typeof config]?.label || label
          : itemConfig?.label

      if (labelFormatter) {
        return (
          <div className={cn("font-medium", labelClassName)}>
            {labelFormatter(value, payload)}
          </div>
        )
      }

      if (!value) {
        return null
      }

      return <div className={cn("font-medium", labelClassName)}>{value}</div>
    }, [
      label,
      labelFormatter,
      payload,
      hideLabel,
      labelClassName,
      config,
      labelKey,
    ])

    if (!active || !payload?.length) {
      return null
    }

    const nestLabel = payload.length === 1 && indicator !== "dot"

    return (
      <div
        ref={ref}
        className={cn(
          "grid min-w-[8rem] items-start gap-1.5 rounded-lg border border-border/50 bg-background px-2.5 py-1.5 text-xs shadow-xl",
          className
        )}
      >
        {!nestLabel ? tooltipLabel : null}
        <div className="grid gap-1.5">
          {payload.map((item, index) => {
            const key = `${nameKey || item.name || item.dataKey || "value"}`
            const itemConfig = getPayloadConfigFromPayload(config, item, key)
            const indicatorColor = color || item.payload.fill || item.color

            return (
              <div
                key={item.dataKey}
                className={cn(
                  "flex w-full flex-wrap items-stretch gap-2 [&>svg]:h-2.5 [&>svg]:w-2.5 [&>svg]:text-muted-foreground",
                  indicator === "dot" && "items-center"
                )}
              >
                {formatter && item?.value !== undefined && item.name ? (
                  formatter(item.value, item.name, item, index, item.payload)
                ) : (
                  <>
                    {itemConfig?.icon ? (
                      <itemConfig.icon />
                    ) : (
                      !hideIndicator && (
                        <div
                          className={cn(
                            "shrink-0 rounded-[2px] border-[--color-border] bg-[--color-bg]",
                            {
                              "h-2.5 w-2.5": indicator === "dot",
                              "w-1": indicator === "line",
                              "w-0 border-[1.5px] border-dashed bg-transparent":
                                indicator === "dashed",
                              "my-0.5": nestLabel && indicator === "dashed",
                            }
                          )}
                          style={
                            {
                              "--color-bg": indicatorColor,
                              "--color-border": indicatorColor,
                            } as React.CSSProperties
                          }
                        />
                      )
                    )}
                    <div
                      className={cn(
                        "flex flex-1 justify-between leading-none",
                        nestLabel ? "items-end" : "items-center"
                      )}
                    >
                      <div className="grid gap-1.5">
                        {nestLabel ? tooltipLabel : null}
                        <span className="text-muted-foreground">
                          {itemConfig?.label || item.name}
                        </span>
                      </div>
                      {item.value && (
                        <span className="font-mono font-medium tabular-nums text-foreground">
                          {item.value.toLocaleString()}
                        </span>
                      )}
                    </div>
                  </>
                )}
              </div>
            )
          })}
        </div>
      </div>
    )
  }
)
ChartTooltipContent.displayName = "ChartTooltip"

const ChartLegend = RechartsPrimitive.Legend

const ChartLegendContent = React.forwardRef<
  HTMLDivElement,
  React.ComponentProps<"div"> &
    Pick<RechartsPrimitive.LegendProps, "payload" | "verticalAlign"> & {
      hideIcon?: boolean
      nameKey?: string
    }
>(
  (
    { className, hideIcon = false, payload, verticalAlign = "bottom", nameKey },
    ref
  ) => {
    const { config } = useChart()

    if (!payload?.length) {
      return null
    }

    return (
      <div
        ref={ref}
        className={cn(
          "flex items-center justify-center gap-4",
          verticalAlign === "top" ? "pb-3" : "pt-3",
          className
        )}
      >
        {payload.map((item) => {
          const key = `${nameKey || item.dataKey || "value"}`
          const itemConfig = getPayloadConfigFromPayload(config, item, key)

          return (
            <div
              key={item.value}
              className={cn(
                "flex items-center gap-1.5 [&>svg]:h-3 [&>svg]:w-3 [&>svg]:text-muted-foreground"
              )}
            >
              {itemConfig?.icon && !hideIcon ? (
                <itemConfig.icon />
              ) : (
                <div
                  className="h-2 w-2 shrink-0 rounded-[2px]"
                  style={{
                    backgroundColor: item.color,
                  }}
                />
              )}
              {itemConfig?.label}
            </div>
          )
        })}
      </div>
    )
  }
)
ChartLegendContent.displayName = "ChartLegend"

// Helper to extract item config from a payload.
function getPayloadConfigFromPayload(
  config: ChartConfig,
  payload: unknown,
  key: string
) {
  if (typeof payload !== "object" || payload === null) {
    return undefined
  }

  const payloadPayload =
    "payload" in payload &&
    typeof payload.payload === "object" &&
    payload.payload !== null
      ? payload.payload
      : undefined

  let configLabelKey: string = key

  if (
    key in payload &&
    typeof payload[key as keyof typeof payload] === "string"
  ) {
    configLabelKey = payload[key as keyof typeof payload] as string
  } else if (
    payloadPayload &&
    key in payloadPayload &&
    typeof payloadPayload[key as keyof typeof payloadPayload] === "string"
  ) {
    configLabelKey = payloadPayload[
      key as keyof typeof payloadPayload
    ] as string
  }

  return configLabelKey in config
    ? config[configLabelKey]
    : config[key as keyof typeof config]
}

export {
  ChartContainer,
  ChartTooltip,
  ChartTooltipContent,
  ChartLegend,
  ChartLegendContent,
  ChartStyle,
}

